import React, { useCallback, useEffect, useState } from 'react';
import { useAppNavigate } from '../../hooks/useAppNavigate';
import { scykRoutes } from '../../config/scykRoutes';
import {
  Button,
  TableCard,
  Pagination,
  LinErpListFilterBar,
  SearchTextInput,
  getErpListRowMenuHint,
} from '@linm-soft-org/linm-web-common-components';
import { ErpFilterCardHeader } from '../../components/layout/ErpFilterCardHeader';
import { medicalIncidentEndpoint } from '../../services/medicalIncidents/endpoint';
import type { MonthlyIncidentReportListItem } from '../../models/MedicalIncident';
import { useAppToast } from '../../hooks/useAppToast';
import { useMonthlyReportPermissions } from '../../hooks/useMonthlyReportPermissions';
import { useResponsive } from '../../hooks/useResponsive';
import { MonthlyReportListRowMenu } from './components/MonthlyReportListRowMenu';
import styles from './MonthlyReportListPage.module.css';

const PAGE_SIZE = 20;
const TEST_ID_PREFIX = 'monthly-report-list';

function fmtDate(iso: string) {
  if (!iso) return '—';
  const [y, m, d] = iso.split('-');
  return `${d}/${m}/${y}`;
}

function periodLabel(dateFrom: string, dateTo: string) {
  const from = new Date(dateFrom + 'T00:00:00');
  const to   = new Date(dateTo   + 'T00:00:00');
  if (from.getFullYear() === to.getFullYear() && from.getMonth() === to.getMonth())
    return `Tháng ${from.getMonth() + 1}/${from.getFullYear()}`;
  return `${fmtDate(dateFrom)} – ${fmtDate(dateTo)}`;
}

const STATUS_LABELS: Record<string, string> = {
  Draft:     'Nháp',
  Submitted: 'Đã gửi',
  Approved:  'Đã duyệt',
};

const STATUS_COLORS: Record<string, { bg: string; text: string; border: string }> = {
  Draft:     { bg: '#f1f5f9', text: '#475569', border: '#cbd5e1' },
  Submitted: { bg: '#fef3c7', text: '#92400e', border: '#fde68a' },
  Approved:  { bg: '#dcfce7', text: '#166534', border: '#bbf7d0' },
};

function statusBadgeStyle(status: string) {
  const c = STATUS_COLORS[status] ?? STATUS_COLORS.Draft;
  return {
    display: 'inline-flex' as const,
    alignItems: 'center' as const,
    gap: 4,
    padding: '2px 10px',
    borderRadius: 999,
    fontSize: 12,
    fontWeight: 700,
    background: c.bg,
    color: c.text,
    border: `1px solid ${c.border}`,
  };
}

const MonthlyReportListPage: React.FC = () => {
  const appNavigate = useAppNavigate();
  const toast    = useAppToast();
  const { isMobile } = useResponsive();
  const { canRead, canCreate } = useMonthlyReportPermissions();

  const [items,      setItems]      = useState<MonthlyIncidentReportListItem[]>([]);
  const [total,      setTotal]      = useState(0);
  const [page,       setPage]       = useState(1);
  const [search,     setSearch]     = useState('');
  const [searchInput, setSearchInput] = useState('');
  const [loading,    setLoading]    = useState(false);

  const totalPages = total > 0 ? Math.ceil(total / PAGE_SIZE) : 1;
  const rowMenuHint = getErpListRowMenuHint(isMobile);

  const load = useCallback(async (p: number, q: string) => {
    setLoading(true);
    try {
      const res = await medicalIncidentEndpoint.getMonthlyReportList(p, PAGE_SIZE, q || undefined);
      setItems(res.items);
      setTotal(res.totalCount);
    } catch (err) {
      toast.fromError(err, 'Tải danh sách báo cáo thất bại');
    } finally {
      setLoading(false);
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    const t = setTimeout(() => { void load(page, search); }, 0);
    return () => clearTimeout(t);
  }, [load, page, search]);

  const applySearch = () => {
    setPage(1);
    setSearch(searchInput.trim());
  };

  const openDetail = (id: string) => {
    appNavigate(scykRoutes.monthlyReports.detail(id));
  };

  if (!canRead) {
    return (
      <div className={styles.page}>
        <div className={styles.emptyRow}>
          <i className="fas fa-lock" style={{ fontSize: 24, marginBottom: 8 }} />
          <div>Bạn không có quyền xem báo cáo tổng hợp hàng tháng.</div>
        </div>
      </div>
    );
  }

  return (
    <div className={styles.page} data-catalog-list-page data-lin-list-layout="erp-filter-bar">
      <div className={styles.pageHeader}>
        <div className={styles.titleGroup}>
          <i className="fas fa-file-medical-alt" />
          <h1 className={styles.title}>Báo Cáo Tổng Hợp Hàng Tháng</h1>
        </div>
        {canCreate && (
          <div className={styles.headerActions}>
            <Button
              variant="primary"
              onClick={() => appNavigate(scykRoutes.monthlyReports.new)}
              data-testid={`${TEST_ID_PREFIX}-create-btn`}
            >
              <i className="fas fa-plus" /> Tạo báo cáo mới
            </Button>
          </div>
        )}
      </div>

      <TableCard
        header={
          <ErpFilterCardHeader title="Danh sách báo cáo" testIdPrefix={TEST_ID_PREFIX}>
            <LinErpListFilterBar
              testIdPrefix={TEST_ID_PREFIX}
              hideDateRange
              onSearch={applySearch}
              loading={loading}
              leading={(
                <div data-testid={`${TEST_ID_PREFIX}-field-search`}>
                  <SearchTextInput
                    label="Tìm kiếm"
                    placeholder="Tìm theo mã, kỳ báo cáo..."
                    value={searchInput}
                    onChange={setSearchInput}
                    testId={`${TEST_ID_PREFIX}-search-text`}
                  />
                </div>
              )}
            />
          </ErpFilterCardHeader>
        }
        footer={
          <Pagination
            currentPage={page}
            totalPages={totalPages}
            totalCount={total}
            pageSize={PAGE_SIZE}
            onPageChange={setPage}
          />
        }
      >
        {rowMenuHint && (
          <div className={styles.rowMenuHint} data-testid={`${TEST_ID_PREFIX}-row-menu-hint`}>
            <i className="fas fa-info-circle" /> {rowMenuHint}
          </div>
        )}
        {loading ? (
          <div className={styles.loadingRow}>
            <i className="fas fa-spinner fa-spin" /> Đang tải...
          </div>
        ) : items.length === 0 ? (
          <div className={styles.emptyRow}>
            <i className="fas fa-inbox" style={{ fontSize: 24, marginBottom: 8 }} />
            <div>{search ? 'Không tìm thấy báo cáo phù hợp.' : 'Chưa có báo cáo nào được tạo.'}</div>
            {!search && canCreate && (
              <Button
                variant="primary"
                className={styles.emptyAction}
                onClick={() => appNavigate(scykRoutes.monthlyReports.new)}
              >
                <i className="fas fa-plus" /> Tạo báo cáo đầu tiên
              </Button>
            )}
          </div>
        ) : (
          <table className={styles.table}>
            <thead>
              <tr>
                <th style={{ width: 44 }}>STT</th>
                <th style={{ width: 180 }}>Số BC</th>
                <th>Kỳ báo cáo</th>
                <th style={{ width: 90, textAlign: 'center' }}>Tổng SC</th>
                <th style={{ width: 60, textAlign: 'center' }}>AI</th>
                <th style={{ width: 100 }}>Trạng thái</th>
                <th style={{ width: 130 }}>Cập nhật</th>
                <th style={{ width: 52 }} aria-label="Thao tác" />
              </tr>
            </thead>
            <tbody>
              {items.map((item, idx) => (
                <TableRow
                  key={item.id}
                  item={item}
                  index={(page - 1) * PAGE_SIZE + idx + 1}
                  onNavigate={() => openDetail(item.id)}
                />
              ))}
            </tbody>
          </table>
        )}
      </TableCard>
    </div>
  );
};

const TableRow: React.FC<{
  item:       MonthlyIncidentReportListItem;
  index:      number;
  onNavigate: () => void;
}> = ({ item, index, onNavigate }) => (
  <tr
    onClick={onNavigate}
    className={styles.tableRow}
    data-testid={`monthly-report-list-row-${item.id}`}
  >
    <td className={styles.sttCell}>{index}</td>
    <td>
      <span className={styles.codeChip}>{item.code || '—'}</span>
    </td>
    <td>
      <strong>{periodLabel(item.dateFrom, item.dateTo)}</strong>
      <div className={styles.dateRange}>{fmtDate(item.dateFrom)} – {fmtDate(item.dateTo)}</div>
    </td>
    <td style={{ textAlign: 'center' }}>
      {item.totalIncidents > 0
        ? <span className={styles.countBadge}>{item.totalIncidents}</span>
        : <span className={styles.muted}>0</span>}
    </td>
    <td style={{ textAlign: 'center' }}>
      {item.aiDraftApplied && <i className="fas fa-robot" title="AI đã phân tích" style={{ color: '#6366f1' }} />}
    </td>
    <td>
      <span style={statusBadgeStyle(item.status)} title={item.status}>
        <i className={`fas ${item.status === 'Submitted' ? 'fa-paper-plane' : item.status === 'Approved' ? 'fa-check-circle' : 'fa-pen'}`} style={{ fontSize: 10 }} />
        {STATUS_LABELS[item.status] ?? item.status}
      </span>
    </td>
    <td className={styles.muted}>
      {new Date(item.updatedAt).toLocaleDateString('vi-VN')}
    </td>
    <td>
      <MonthlyReportListRowMenu onAction={() => onNavigate()} />
    </td>
  </tr>
);

export default MonthlyReportListPage;
